// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function _run(uint256 proposalID) internal {
        uint256 returnedWeight;
        try c.voteProposal(proposalID) returns (uint256 __r) { returnedWeight = __r; } catch { return; }
        uint256 memberVotesAfter;
        try c.mapPIDMember_votes(proposalID, address(this)) returns (uint256 __r) { memberVotesAfter = __r; } catch { return; }
        assertTrue(returnedWeight == memberVotesAfter);
    }

    function testFuzz_run(uint256 proposalID) public {
        _run(proposalID);
    }

    receive() external payable {}
}
